def entry(legal, steps, rights, case, answer, pitfall, sources):
    return dict(legal=legal, steps=steps, rights=rights, case=case, answer=answer, pitfall=pitfall, sources=sources)

def source(title, url, category='legislation'):
    return dict(title=title, url=url, category=category)
